from b3 import *
mg=""
for i,(n,s) in enumerate([("launch-hero.png","1.2 MB"),("studio-bts-01.jpg","840 KB"),("q4-teaser.png","2.4 MB"),("reel-cut.mp4","18 MB"),("team-photo.jpg","1.1 MB"),("quote-card.png","320 KB"),("webinar.png","610 KB"),("product-ui.png","1.8 MB"),("bf-promo.jpg","900 KB"),("thread-cover.png","410 KB"),("office-dog.jpg","1.3 MB"),("logo-pack.png","220 KB")]):
    vid='<span class="badge nodot" style="position:absolute;left:8px;bottom:8px;background:rgba(15,23,42,.8);color:#fff">▶ 0:24</span>' if n.endswith("mp4") else ""
    sel='<span class="check on" style="position:absolute;top:8px;left:8px"></span>' if i==2 else ""
    ol="outline:2px solid var(--primary);outline-offset:2px;" if i==2 else ""
    mg+=f'<div class="card" style="overflow:hidden;{ol}"><div class="th{1+i%6}" style="aspect-ratio:1;position:relative">{vid}{sel}</div><div style="padding:8px 10px"><div class="xs" style="font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{n}</div><div class="xs subtle">{s}</div></div></div>'
page("media","Media library",shell("media",head("Media library","Images and videos ready to use in posts.",f'<a class="btn btn-secondary">1 selected · Use in post</a><a class="btn btn-primary">{I("upload")}Upload</a>')+
f'''<div class="row between"><div class="seg"><a class="active">All · 128</a><a>Images</a><a>Videos</a><a>Unused</a></div><div class="row sm subtle" style="width:260px">2.1 GB of 10 GB<div class="progress grow"><i style="width:21%"></i></div></div></div>
<div class="dropzone" style="justify-content:center;padding:28px">{I("upload","ico","color:var(--primary);width:24px;height:24px")}<div><b>Drag files here to upload</b><div class="sm muted">PNG, JPG, GIF, MP4 · up to 8MB for images, 512MB for video</div></div></div>
<div class="grid" style="grid-template-columns:repeat(6,1fr);gap:14px">{mg}</div>'''))

roles="".join(f'<div class="card card-pad"><div class="row"><span class="badge {c} nodot">{r}</span><span class="xs subtle grow" style="text-align:right">{n} members</span></div><p class="sm muted" style="margin-top:10px">{d}</p></div>' for r,c,n,d in [("Admin","b-primary",1,"Full access, billing, channels and team management."),("Editor","b-info",2,"Create, schedule and approve posts on all channels."),("Contributor","",2,"Draft posts and submit them for approval.")])
tr=""
for i,(a,n,e,r,c,l) in enumerate([("WK","Win Kyaw (you)","win@acmestudio.co","Admin","x in ig","Now"),("MS","Maya Santos","maya@acmestudio.co","Editor","x in ig","12 min ago"),("JL","Jon Lee","jon@acmestudio.co","Editor","in","Yesterday"),("PT","Priya Thomas","priya@acmestudio.co","Contributor","x in ig","3 days ago"),("DF","dan@freelance.io","Invited 2 days ago","Contributor","ig","—")]):
    chs="".join(ch(k,"sm") for k in c.split())
    end='<span class="badge b-warning">Invite pending</span>' if l=="—" else f'<button class="btn btn-ghost btn-icon btn-sm" aria-label="More">{I("more")}</button>'
    tr+=f'<tr><td><div class="row">{av(a,i)}<div><b class="sm">{n}</b><div class="xs subtle">{e}</div></div></div></td><td><div class="input row between sm" style="width:150px;height:34px">{r}<span class="subtle">▾</span></div></td><td><div class="row" style="gap:4px">{chs}</div></td><td class="sm muted">{l}</td><td style="text-align:right">{end}</td></tr>'
page("team","Team",shell("team",head("Team","Invite teammates and control what they can do.",f'<a class="btn btn-primary">{I("plus")}Invite member</a>')+f'<div class="grid g3">{roles}</div><div class="card"><table class="table"><thead><tr><th>Member</th><th>Role</th><th>Channels</th><th>Last active</th><th></th></tr></thead><tbody>{tr}</tbody></table></div>'))

def settings(slug,tab,inner):
    tabs="".join(f'<a class="{"active" if t==tab else ""}" href="{s}.html">{t}</a>' for t,s in [("Profile","settings"),("Billing & plan","settings-billing"),("Notifications","settings-notifications"),("Workspace","settings"),("Security","settings")])
    page(slug,f"Settings · {tab}",shell("settings",head("Settings","Manage your account and workspace preferences.")+f'<div class="tabs">{tabs}</div>'+inner))
themes=""
for i,(n,b) in enumerate([("Light","#F8FAFC"),("Dark","#0B1120"),("System","linear-gradient(90deg,#F8FAFC 50%,#0B1120 50%)")]):
    ol="outline:2px solid var(--primary);" if i==2 else ""
    themes+=f'<div class="card" style="padding:10px;{ol}"><div style="height:80px;border-radius:8px;background:{b};border:1px solid var(--border)"></div><div class="row sm" style="margin-top:8px"><span class="check {"on" if i==2 else ""}" style="border-radius:50%"></span>{n}</div></div>'
settings("settings","Profile",f'''<div class="grid" style="grid-template-columns:280px 1fr;gap:32px"><div><h3>Personal info</h3><p class="sm muted">Shown to teammates on posts and approvals.</p></div><div class="card card-pad col" style="gap:18px"><div class="row">{av("WK",0,64)}<div class="col" style="gap:6px"><div class="row"><a class="btn btn-sm btn-secondary">Change photo</a><a class="btn btn-sm btn-ghost">Remove</a></div><span class="xs subtle">JPG or PNG, at least 256×256</span></div></div>
<div class="grid g2" style="gap:16px"><div class="field"><label class="label">Full name</label><input class="input" value="Win Htet Kyaw"></div><div class="field"><label class="label">Email</label><input class="input" value="win@acmestudio.co"></div><div class="field"><label class="label">Timezone</label><div class="input row between">Asia/Bangkok (GMT+7)<span class="subtle">▾</span></div><span class="hint">Default for scheduling.</span></div><div class="field"><label class="label">Language</label><div class="input row between">English (US)<span class="subtle">▾</span></div></div></div></div>
<div><h3>Appearance</h3><p class="sm muted">Choose how socialcastly looks to you.</p></div><div class="grid g3" style="gap:14px">{themes}</div>
<div><h3 style="color:var(--error)">Danger zone</h3></div><div class="card card-pad row between" style="border-color:color-mix(in srgb,var(--error) 40%,var(--border))"><div><b>Delete account</b><div class="sm muted">Permanently remove your account and all scheduled posts.</div></div><a class="btn btn-danger">Delete account</a></div></div>
<div class="row" style="justify-content:flex-end;border-top:1px solid var(--border);padding-top:16px"><a class="btn btn-secondary">Cancel</a><a class="btn btn-primary">Save changes</a></div>''')
usage="".join(f'<div style="background:rgba(255,255,255,.16);border-radius:10px;padding:12px"><div class="xs">{a}</div><b style="font-size:18px">{b}</b><div style="height:5px;background:rgba(255,255,255,.3);border-radius:4px;margin-top:8px"><i style="display:block;height:100%;width:{p}%;background:#fff;border-radius:4px"></i></div></div>' for a,b,p in [("Channels","4 / 10",40),("Seats","3 / 3",100),("Scheduled","24 / ∞",12)])
inv="".join(f'<tr><td class="sm">{d}</td><td class="sm">{x}</td><td class="sm">{a}</td><td>{badge(s,l)}</td><td style="text-align:right"><a class="btn btn-sm btn-ghost">Download PDF</a></td></tr>' for d,x,a,s,l in [("Oct 7, 2026","Pro · monthly","$15.00","published","Paid"),("Sep 7, 2026","Pro · monthly","$15.00","published","Paid"),("Aug 7, 2026","Pro · monthly","$15.00","failed","Failed · retried")])
settings("settings-billing","Billing & plan",f'''<div class="grid" style="grid-template-columns:1.4fr 1fr;align-items:stretch"><div class="card card-pad col" style="background:linear-gradient(135deg,#4F46E5,#7C3AED);color:#fff;border:0"><div class="row between"><span class="badge nodot" style="background:rgba(255,255,255,.2);color:#fff">Current plan</span><span class="sm">Trial ends Nov 7, 2026</span></div><div><span style="font-size:36px;font-weight:800">Pro</span><span> · $15 / month, billed monthly</span></div>
<div class="grid g3" style="gap:12px">{usage}</div><div class="row"><a class="btn" style="background:#fff;color:#4338CA">Upgrade to Business</a><a class="btn" style="color:#fff;border-color:rgba(255,255,255,.6)">Switch to annual · save 20%</a></div></div>
<div class="card card-pad col"><h3>Payment method</h3><div class="row card" style="padding:14px;box-shadow:none"><span class="badge nodot" style="background:#1A1F71;color:#fff">VISA</span><div class="grow"><b class="sm">•••• 4242</b><div class="xs subtle">Expires 08/28</div></div><a class="btn btn-sm btn-ghost">Edit</a></div><h3 style="margin-top:8px">Billing email</h3><span class="sm muted">billing@acmestudio.co</span><a class="btn btn-ghost btn-sm" style="align-self:flex-start;color:var(--error);padding:0">Cancel subscription</a></div></div>
<div class="card"><div class="card-head"><h2>Invoices</h2></div><table class="table"><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>{inv}</tbody></table></div>''')
nr=""
for a,b,c in [("Post failed to publish","When a network rejects a post or retries are exhausted","111"),("Post published","Confirmation each time a post goes live","010"),("Approval requested","A teammate submits a draft for your review","111"),("Approval decision","Your draft is approved, rejected or needs changes","110"),("Channel needs reconnecting","Access token is expiring or revoked","111"),("Weekly performance digest","Every Monday at 9:00 AM","100")]:
    tg="".join(f'<td><span class="toggle {"on" if x=="1" else ""}" role="switch" aria-checked="{"true" if x=="1" else "false"}"></span></td>' for x in c)
    nr+=f'<tr><td><b class="sm">{a}</b><div class="xs subtle">{b}</div></td>{tg}</tr>'
settings("settings-notifications","Notifications",f'''<div class="card"><table class="table"><thead><tr><th>Event</th><th style="width:110px">Email</th><th style="width:110px">In-app</th><th style="width:110px">Push</th></tr></thead><tbody>{nr}</tbody></table></div>
<div class="card card-pad row between"><div><b>Quiet hours</b><div class="sm muted">Pause push notifications 10:00 PM – 7:00 AM (GMT+7)</div></div><span class="toggle on"></span></div>''')

skel="".join('<div class="post"><div class="skel" style="width:54px;height:14px"></div><div class="skel" style="width:36px;height:36px;border-radius:50%"></div><div class="body col" style="gap:8px"><div class="skel" style="width:40%;height:12px"></div><div class="skel" style="width:95%;height:12px"></div><div class="skel" style="width:70%;height:12px"></div></div></div>' for _ in range(3))
toasts="".join(f'<div class="toast"><span class="bar" style="background:var(--{c})"></span><div class="grow"><b class="sm">{t}</b><div class="xs muted">{d}</div></div><span class="muted">✕</span></div>' for c,t,d in [("success","3 posts scheduled","Thu, Oct 29 at 9:00 AM · Undo"),("error","Couldn't publish to X","Rate limit reached. Retrying in 12 min."),("warning","Instagram needs reconnecting","Access expires in 5 days."),("primary","Draft saved","Autosaved just now")])
page("states","Empty, loading & error states",shell("queue",head("States","Empty, loading, error and feedback patterns used across the app.")+
f'''<div class="grid g3" style="align-items:start"><div class="card"><div class="card-head"><h3>Empty · Queue</h3></div><div class="empty"><div class="art">{MARK.format(w=52)}</div><h2>Your queue is empty</h2><p class="muted sm" style="max-width:260px">Schedule your first post and it'll appear here, ready to cast.</p><a class="btn btn-primary" href="composer.html">{I("plus")}Create a post</a></div></div>
<div class="card"><div class="card-head"><h3>Loading · Skeleton</h3></div>{skel}</div>
<div class="card"><div class="card-head"><h3>Error · Failed load</h3></div><div class="empty"><div class="art" style="background:var(--error-soft);color:var(--error)">{I("alert","ico","width:44px;height:44px")}</div><h2>We couldn't load your calendar</h2><p class="muted sm" style="max-width:280px">The server didn't respond (503). Your scheduled posts are safe.</p><div class="row"><a class="btn btn-secondary">Contact support</a><a class="btn btn-primary">{I("retry")}Try again</a></div></div></div></div>
<div class="grid g2" style="align-items:start"><div class="card card-pad col"><h3>Toasts</h3>{toasts}</div>
<div class="card" style="position:relative;height:430px;overflow:hidden"><div class="card-pad"><h3>Confirm modal</h3></div><div class="modal-wrap"><div class="modal"><div style="padding:24px" class="col"><div style="width:44px;height:44px;border-radius:12px;background:var(--error-soft);color:var(--error);display:grid;place-items:center">{I("alert")}</div><h2>Disconnect @acmestudio?</h2><p class="sm muted">4 scheduled posts for this X account will move to drafts. You can reconnect anytime.</p></div><div class="row" style="justify-content:flex-end;padding:16px 24px;border-top:1px solid var(--border);background:var(--surface-2);border-radius:0 0 20px 20px"><a class="btn btn-secondary">Cancel</a><a class="btn btn-danger">Disconnect</a></div></div></div></div></div>'''),group="System")

sw=lambda n: f'<div class="col" style="gap:6px"><div style="height:56px;border-radius:10px;background:var(--{n});border:1px solid var(--border)"></div><div class="xs"><b>--{n}</b></div></div>'
chl="".join(f'<div class="row sm">{ch(k)}{CH[k][0].capitalize()}</div>' for k in CH)
bdg="".join(badge(s) for s in ["scheduled","queued","published","pending","failed","draft"])
sp="".join(f'<div class="row xs"><span style="width:52px">{v}px</span><i style="height:10px;width:{v*2}px;background:var(--primary);border-radius:3px"></i></div>' for v in [4,8,12,16,24,32,48,64])
rad="".join(f'<div style="width:56px;height:56px;background:var(--primary-soft);border:1.5px solid var(--primary);border-radius:{r}"></div>' for r in ["6px","10px","14px","20px","999px"])
elev="".join(f'<div style="flex:1;height:64px;border-radius:12px;background:var(--surface);box-shadow:var(--shadow-{s});border:1px solid var(--border);padding:8px" class="xs muted">shadow-{s}</div>' for s in ["sm","md","lg"])
page("design-system","Design system",shell("settings",head("Design system","Tokens and components powering socialcastly — light & dark.")+
f'''<div class="card card-pad grid" style="grid-template-columns:1fr 1fr;align-items:center"><div class="col"><h2>Brand</h2><div>{logo("lockup",48)}</div><p class="sm muted">Concentric-arc “C” mark with dot + lowercase wordmark. Gradient: light #4F46E5→#7C3AED, dark #818CF8→#A78BFA. “social” is #0F172A in light, white in dark.</p></div><div class="row" style="justify-content:flex-end;gap:20px">{MARK.format(w=96)}<img src="../assets/logo/app-icon-128.png" style="width:96px;border-radius:22px" alt=""></div></div>
<div class="card card-pad col"><h2>Color</h2><div class="grid" style="grid-template-columns:repeat(8,1fr);gap:12px">{"".join(sw(n) for n in ["bg","surface","surface-2","border","text","text-2","text-3","primary","primary-2","primary-soft","success","warning","error","info","success-soft","error-soft"])}</div><h3>Channels</h3><div class="row wrap" style="gap:16px">{chl}</div></div>
<div class="grid g2" style="align-items:start"><div class="card card-pad col"><h2>Typography · Inter</h2><div style="font-size:56px;font-weight:800;letter-spacing:-.035em;line-height:1">Display 56</div><h1>Heading 28 / Bold</h1><h2>Title 18 / Semibold</h2><h3>Subtitle 16 / Semibold</h3><p>Body 14 / Regular — The quick brown fox schedules a post.</p><p class="sm muted">Small 13 / text-2</p><p class="xs subtle">Caption 12 / text-3</p></div>
<div class="card card-pad col"><h2>Buttons</h2><div class="row wrap"><a class="btn btn-primary">Primary</a><a class="btn btn-grad">Gradient CTA</a><a class="btn btn-secondary">Secondary</a><a class="btn btn-ghost">Ghost</a><a class="btn btn-danger">Danger</a></div><div class="row wrap"><a class="btn btn-primary btn-sm">Small</a><a class="btn btn-primary btn-lg">Large</a><a class="btn btn-secondary btn-icon" aria-label="More">{I("more")}</a></div>
<h2>Badges</h2><div class="row wrap">{bdg}</div><h2>Inputs & controls</h2><div class="grid g2" style="gap:12px"><div class="field"><label class="label">Default</label><input class="input" placeholder="Placeholder"></div><div class="field"><label class="label">Error</label><input class="input err" value="win@"><span class="err-text">Invalid email</span></div></div><div class="row"><span class="toggle on"></span><span class="toggle"></span><span class="check on"></span><span class="check"></span><div class="seg"><a class="active">Week</a><a>Month</a></div></div></div></div>
<div class="grid g3" style="align-items:start"><div class="card card-pad col"><h2>Spacing · 4pt</h2>{sp}</div><div class="card card-pad col"><h2>Radius</h2><div class="row wrap">{rad}</div><p class="xs subtle">6 · 10 · 14 · 20 · full</p></div><div class="card card-pad col"><h2>Elevation</h2><div class="row">{elev}</div></div></div>
<div class="grid g2" style="align-items:start"><div class="card"><div class="card-head"><h2>Post card</h2></div>{post_row(POSTS[2])}{post_row(POSTS[3])}</div><div class="card card-pad col"><h2>Calendar cell</h2><div class="cal" style="grid-template-columns:repeat(3,1fr)"><div class="cell"><span class="n">28</span><div class="chip c-in"><b>11:30</b>Rebuild story</div></div><div class="cell today"><span class="n">29</span><div class="chip c-x"><b>9:00</b>Launch day</div><div class="chip c-ig failed"><b>16:00</b>Quick tip</div></div><div class="cell out"><span class="n">1</span></div></div></div></div>'''),group="System")
